<section class="panel"><h2>Configurar contraseña</h2><form method="post" class="form-grid"><label>Longitud (6 a 64)<input type="number" name="length" min="6" max="64" value="16"></label><div class="checks"><label><input type="checkbox" name="lower" checked> Minúsculas</label><label><input type="checkbox" name="upper" checked> Mayúsculas</label><label><input type="checkbox" name="numbers" checked> Números</label><label><input type="checkbox" name="symbols" checked> Símbolos</label></div><button class="btn" name="generate" value="1">Generar contraseña</button></form><?php if($password): ?><div class="password-result"><code id="generatedPassword"><?=e($password)?></code><button class="btn secondary" onclick="copyPassword()" type="button">Copiar</button></div><?php endif ?></section>
